insert into public.categories (id, name, description, icon, tone, position) values
  ('web-development', 'Desarrollo web', 'Conceptos esenciales para crear interfaces y aplicaciones web.', 'code', 'violet', 1),
  ('data-databases', 'Datos y bases de datos', 'Vocabulario para almacenar, consultar y organizar información.', 'database', 'blue', 2),
  ('cybersecurity', 'Ciberseguridad', 'Términos básicos para comprender riesgos y protección digital.', 'shield', 'green', 3);
insert into public.words (id, category_id, term, translation, definition, definition_es, example, pronunciation_phrase, pronunciation_hint, difficulty, synonyms, antonyms, keywords, position) values
  ('web-browser', 'web-development', 'Browser', 'Navegador', 'A program used to access and display websites.', 'Programa utilizado para acceder y mostrar sitios web.', 'The browser displays the new website.', 'The browser displays the new website.', 'brau-ser', 'beginner', array['web browser'], '{}'::text[], array['program', 'website', 'display'], 1),
  ('web-component', 'web-development', 'Component', 'Componente', 'A reusable part of a user interface.', 'Parte reutilizable de una interfaz de usuario.', 'This button is a reusable component.', 'This button is a reusable component.', 'com-póu-nent', 'beginner', array['module', 'element'], '{}'::text[], array['reusable', 'interface', 'part'], 2),
  ('web-deploy', 'web-development', 'Deploy', 'Desplegar', 'To publish an application so people can use it.', 'Publicar una aplicación para que las personas puedan utilizarla.', 'We deploy the application on Friday.', 'We deploy the application on Friday.', 'di-plói', 'beginner', array['publish', 'release'], array['withdraw'], array['publish', 'application', 'release'], 3),
  ('web-endpoint', 'web-development', 'Endpoint', 'Punto de acceso', 'A specific address where an API receives requests.', 'Dirección específica donde una API recibe solicitudes.', 'The endpoint returns the user profile.', 'The endpoint returns the user profile.', null, 'intermediate', array['API route'], '{}'::text[], array['address', 'API', 'request'], 4),
  ('web-framework', 'web-development', 'Framework', 'Marco de trabajo', 'A structured set of tools for building software.', 'Conjunto estructurado de herramientas para construir software.', 'React is used with a modern web framework.', 'React is used with a modern web framework.', null, 'intermediate', array['software framework'], '{}'::text[], array['tools', 'structure', 'software'], 5),
  ('web-frontend', 'web-development', 'Frontend', 'Interfaz del cliente', 'The part of an application that users see and interact with.', 'Parte de una aplicación que los usuarios ven y utilizan.', 'The frontend adapts to mobile screens.', 'The frontend adapts to mobile screens.', null, 'beginner', array['client side'], '{}'::text[], array['user', 'interface', 'client'], 6),
  ('web-backend', 'web-development', 'Backend', 'Lógica del servidor', 'The server-side part that manages logic and data.', 'Parte del servidor que administra lógica y datos.', 'The backend validates the request.', 'The backend validates the request.', null, 'beginner', array['server side'], '{}'::text[], array['server', 'logic', 'data'], 7),
  ('web-layout', 'web-development', 'Layout', 'Diseño de página', 'The arrangement of visual elements on a page.', 'Organización de los elementos visuales en una página.', 'The layout has two columns on desktop.', 'The layout has two columns on desktop.', null, 'beginner', array['arrangement', 'structure'], '{}'::text[], array['arrangement', 'page', 'visual'], 8),
  ('web-library', 'web-development', 'Library', 'Biblioteca', 'A collection of reusable code for specific tasks.', 'Colección de código reutilizable para tareas específicas.', 'The icon library keeps the design consistent.', 'The icon library keeps the design consistent.', null, 'beginner', array['code collection'], '{}'::text[], array['code', 'collection', 'reusable'], 9),
  ('web-link', 'web-development', 'Link', 'Enlace', 'An element that takes a user to another location.', 'Elemento que lleva al usuario a otra ubicación.', 'Click the link to open your profile.', 'Click the link to open your profile.', null, 'beginner', array['hyperlink'], '{}'::text[], array['navigate', 'location', 'click'], 10),
  ('web-responsive', 'web-development', 'Responsive', 'Adaptable', 'Able to adjust to different screen sizes.', 'Capaz de adaptarse a diferentes tamaños de pantalla.', 'The responsive page works well on phones.', 'The responsive page works well on phones.', null, 'beginner', array['adaptive'], array['fixed'], array['screen', 'adapt', 'mobile'], 11),
  ('web-route', 'web-development', 'Route', 'Ruta', 'A path that identifies a page or application resource.', 'Camino que identifica una página o recurso de la aplicación.', 'The profile route opens a new screen.', 'The profile route opens a new screen.', null, 'beginner', array['path'], '{}'::text[], array['path', 'page', 'navigation'], 12),
  ('web-state', 'web-development', 'State', 'Estado', 'Data that represents the current condition of an interface.', 'Datos que representan la condición actual de una interfaz.', 'The component state stores the selected answer.', 'The component state stores the selected answer.', null, 'intermediate', array['status', 'condition'], '{}'::text[], array['data', 'current', 'interface'], 13),
  ('web-style', 'web-development', 'Style', 'Estilo', 'Visual rules that control how elements look.', 'Reglas visuales que controlan la apariencia de los elementos.', 'The style uses a violet color palette.', 'The style uses a violet color palette.', null, 'beginner', array['appearance', 'design'], '{}'::text[], array['visual', 'appearance', 'rules'], 14),
  ('web-template', 'web-development', 'Template', 'Plantilla', 'A predefined structure used to create similar content.', 'Estructura predefinida utilizada para crear contenido similar.', 'The template provides a consistent page structure.', 'The template provides a consistent page structure.', null, 'beginner', array['pattern', 'blueprint'], '{}'::text[], array['predefined', 'structure', 'content'], 15),
  ('web-user-interface', 'web-development', 'User interface', 'Interfaz de usuario', 'The visual controls through which a person uses a system.', 'Controles visuales mediante los cuales una persona utiliza un sistema.', 'The user interface is clear and accessible.', 'The user interface is clear and accessible.', null, 'beginner', array['UI'], '{}'::text[], array['visual', 'controls', 'user'], 16),
  ('web-accessibility', 'web-development', 'Accessibility', 'Accesibilidad', 'The practice of making software usable by more people.', 'Práctica de hacer que el software pueda ser utilizado por más personas.', 'Accessibility improves keyboard navigation.', 'Accessibility improves keyboard navigation.', null, 'intermediate', array['inclusive design'], '{}'::text[], array['usable', 'inclusive', 'people'], 17),
  ('web-cache', 'web-development', 'Cache', 'Caché', 'Temporary storage that helps data load faster.', 'Almacenamiento temporal que ayuda a cargar datos más rápido.', 'The browser cache stores the image.', 'The browser cache stores the image.', null, 'intermediate', array['temporary storage'], '{}'::text[], array['temporary', 'storage', 'faster'], 18),
  ('web-debug', 'web-development', 'Debug', 'Depurar', 'To find and correct problems in software.', 'Encontrar y corregir problemas en el software.', 'Developers debug the navigation error.', 'Developers debug the navigation error.', null, 'beginner', array['troubleshoot'], '{}'::text[], array['find', 'correct', 'problem'], 19),
  ('web-render', 'web-development', 'Render', 'Renderizar', 'To produce the visible output of a page or component.', 'Producir la salida visible de una página o componente.', 'React renders the updated component.', 'React renders the updated component.', null, 'intermediate', array['display', 'draw'], '{}'::text[], array['visible', 'output', 'component'], 20),
  ('data-backup', 'data-databases', 'Backup', 'Copia de seguridad', 'A copy of data kept in case the original is lost.', 'Copia de datos conservada por si se pierde el original.', 'The system creates a backup every night.', 'The system creates a backup every night.', null, 'beginner', array['copy'], '{}'::text[], array['copy', 'data', 'lost'], 1),
  ('data-column', 'data-databases', 'Column', 'Columna', 'A vertical set of values of one type in a table.', 'Conjunto vertical de valores de un tipo en una tabla.', 'The email column contains text values.', 'The email column contains text values.', null, 'beginner', array['attribute'], '{}'::text[], array['vertical', 'table', 'values'], 2),
  ('data-database', 'data-databases', 'Database', 'Base de datos', 'An organized collection of information.', 'Colección organizada de información.', 'The database stores student progress.', 'The database stores student progress.', null, 'beginner', array['data store'], '{}'::text[], array['organized', 'information', 'store'], 3),
  ('data-dataset', 'data-databases', 'Dataset', 'Conjunto de datos', 'A related collection of data used for analysis.', 'Colección relacionada de datos utilizada para análisis.', 'The dataset contains sixty technical words.', 'The dataset contains sixty technical words.', null, 'beginner', array['data collection'], '{}'::text[], array['collection', 'analysis', 'data'], 4),
  ('data-field', 'data-databases', 'Field', 'Campo', 'A named place that stores one piece of information.', 'Lugar con nombre que guarda una unidad de información.', 'The name field is required.', 'The name field is required.', null, 'beginner', array['attribute'], '{}'::text[], array['named', 'information', 'value'], 5),
  ('data-filter', 'data-databases', 'Filter', 'Filtro', 'A rule that selects only matching data.', 'Regla que selecciona únicamente los datos coincidentes.', 'Use a filter to show advanced words.', 'Use a filter to show advanced words.', null, 'beginner', array['screen', 'selection'], '{}'::text[], array['select', 'matching', 'rule'], 6),
  ('data-index', 'data-databases', 'Index', 'Índice', 'A structure that makes database searches faster.', 'Estructura que acelera las búsquedas en una base de datos.', 'The index improves the search speed.', 'The index improves the search speed.', null, 'intermediate', array['lookup structure'], '{}'::text[], array['search', 'faster', 'structure'], 7),
  ('data-key', 'data-databases', 'Key', 'Clave', 'A value used to identify or connect stored records.', 'Valor utilizado para identificar o conectar registros almacenados.', 'Each user has a unique key.', 'Each user has a unique key.', null, 'intermediate', array['identifier'], '{}'::text[], array['identify', 'unique', 'record'], 8),
  ('data-query', 'data-databases', 'Query', 'Consulta', 'A request to retrieve or modify stored data.', 'Solicitud para recuperar o modificar datos almacenados.', 'The query returns all active users.', 'The query returns all active users.', null, 'intermediate', array['request'], '{}'::text[], array['request', 'retrieve', 'data'], 9),
  ('data-record', 'data-databases', 'Record', 'Registro', 'A group of related fields describing one item.', 'Grupo de campos relacionados que describen un elemento.', 'This record describes one learning session.', 'This record describes one learning session.', null, 'beginner', array['entry'], '{}'::text[], array['fields', 'item', 'entry'], 10),
  ('data-restore', 'data-databases', 'Restore', 'Restaurar', 'To recover data from a saved copy.', 'Recuperar datos desde una copia guardada.', 'We restore the profile from the backup.', 'We restore the profile from the backup.', null, 'beginner', array['recover'], array['erase'], array['recover', 'backup', 'data'], 11),
  ('data-row', 'data-databases', 'Row', 'Fila', 'A horizontal group of related values in a table.', 'Grupo horizontal de valores relacionados en una tabla.', 'Each row represents one student.', 'Each row represents one student.', null, 'beginner', array['record'], '{}'::text[], array['horizontal', 'table', 'values'], 12),
  ('data-schema', 'data-databases', 'Schema', 'Esquema', 'A formal description of how data is structured.', 'Descripción formal de cómo se estructuran los datos.', 'The schema defines the profile fields.', 'The schema defines the profile fields.', null, 'intermediate', array['data model'], '{}'::text[], array['structure', 'model', 'fields'], 13),
  ('data-sort', 'data-databases', 'Sort', 'Ordenar', 'To arrange data according to a chosen rule.', 'Organizar datos según una regla elegida.', 'Sort the words by difficulty.', 'Sort the words by difficulty.', null, 'beginner', array['order', 'arrange'], array['shuffle'], array['arrange', 'order', 'rule'], 14),
  ('data-storage', 'data-databases', 'Storage', 'Almacenamiento', 'A place or system used to keep digital information.', 'Lugar o sistema utilizado para conservar información digital.', 'Local storage keeps the user progress.', 'Local storage keeps the user progress.', null, 'beginner', array['data store'], '{}'::text[], array['keep', 'digital', 'information'], 15),
  ('data-table', 'data-databases', 'Table', 'Tabla', 'Data organized into rows and columns.', 'Datos organizados en filas y columnas.', 'The table lists every category.', 'The table lists every category.', null, 'beginner', array['relation'], '{}'::text[], array['rows', 'columns', 'organized'], 16),
  ('data-transaction', 'data-databases', 'Transaction', 'Transacción', 'A group of data operations treated as one unit.', 'Grupo de operaciones de datos tratado como una unidad.', 'The transaction saves all changes together.', 'The transaction saves all changes together.', null, 'advanced', array['unit of work'], '{}'::text[], array['operations', 'unit', 'changes'], 17),
  ('data-validation', 'data-databases', 'Validation', 'Validación', 'The process of checking whether data follows rules.', 'Proceso de comprobar si los datos cumplen reglas.', 'Validation rejects an empty name.', 'Validation rejects an empty name.', null, 'beginner', array['verification'], '{}'::text[], array['checking', 'rules', 'data'], 18),
  ('data-value', 'data-databases', 'Value', 'Valor', 'A specific piece of information stored in a field.', 'Dato específico almacenado en un campo.', 'The XP value is three hundred.', 'The XP value is three hundred.', null, 'beginner', array['data item'], '{}'::text[], array['information', 'field', 'stored'], 19),
  ('data-export', 'data-databases', 'Export', 'Exportar', 'To convert and save data for use elsewhere.', 'Convertir y guardar datos para utilizarlos en otro lugar.', 'The user can export the progress report.', 'The user can export the progress report.', null, 'beginner', array['extract'], array['import'], array['save', 'convert', 'elsewhere'], 20),
  ('security-access', 'cybersecurity', 'Access', 'Acceso', 'Permission or ability to enter and use a system.', 'Permiso o capacidad para entrar y utilizar un sistema.', 'Only teachers have access to this panel.', 'Only teachers have access to this panel.', null, 'beginner', array['entry', 'permission'], '{}'::text[], array['permission', 'enter', 'system'], 1),
  ('security-attack', 'cybersecurity', 'Attack', 'Ataque', 'An attempt to damage or gain unauthorized access to a system.', 'Intento de dañar o acceder sin autorización a un sistema.', 'The firewall blocks the attack.', 'The firewall blocks the attack.', null, 'beginner', '{}'::text[], array['defense'], array['damage', 'unauthorized', 'system'], 2),
  ('security-authentication', 'cybersecurity', 'Authentication', 'Autenticación', 'The process of proving a user identity.', 'Proceso de demostrar la identidad de un usuario.', 'Authentication requires a password and a code.', 'Authentication requires a password and a code.', null, 'intermediate', array['identity verification'], '{}'::text[], array['identity', 'prove', 'user'], 3),
  ('security-authorization', 'cybersecurity', 'Authorization', 'Autorización', 'The process of deciding what an identified user may do.', 'Proceso de decidir qué puede hacer un usuario identificado.', 'Authorization allows the administrator to edit users.', 'Authorization allows the administrator to edit users.', null, 'intermediate', array['permission'], '{}'::text[], array['permission', 'user', 'action'], 4),
  ('security-breach', 'cybersecurity', 'Breach', 'Brecha de seguridad', 'An incident where protected data or systems are exposed.', 'Incidente en el que se exponen datos o sistemas protegidos.', 'The company reported a data breach.', 'The company reported a data breach.', null, 'intermediate', array['security incident'], '{}'::text[], array['exposed', 'data', 'incident'], 5),
  ('security-credential', 'cybersecurity', 'Credential', 'Credencial', 'Information used to prove identity or access rights.', 'Información utilizada para demostrar identidad o derechos de acceso.', 'Never share your login credentials.', 'Never share your login credentials.', null, 'intermediate', array['login details'], '{}'::text[], array['identity', 'access', 'login'], 6),
  ('security-encryption', 'cybersecurity', 'Encryption', 'Cifrado', 'The process of transforming data so unauthorized people cannot read it.', 'Proceso de transformar datos para impedir su lectura no autorizada.', 'Encryption protects the stored message.', 'Encryption protects the stored message.', null, 'intermediate', array['enciphering'], array['decryption'], array['transform', 'protect', 'data'], 7),
  ('security-firewall', 'cybersecurity', 'Firewall', 'Cortafuegos', 'A security system that controls network traffic.', 'Sistema de seguridad que controla el tráfico de red.', 'The firewall rejects suspicious traffic.', 'The firewall rejects suspicious traffic.', null, 'beginner', array['network filter'], '{}'::text[], array['network', 'traffic', 'control'], 8),
  ('security-hacker', 'cybersecurity', 'Hacker', 'Especialista o atacante informático', 'A person who explores or attempts to access computer systems.', 'Persona que explora o intenta acceder a sistemas informáticos.', 'An ethical hacker tests the application security.', 'An ethical hacker tests the application security.', null, 'intermediate', array['intruder'], '{}'::text[], array['person', 'access', 'system'], 9),
  ('security-malware', 'cybersecurity', 'Malware', 'Software malicioso', 'Software designed to damage, disrupt, or steal information.', 'Software diseñado para dañar, interrumpir o robar información.', 'The antivirus detected malware.', 'The antivirus detected malware.', null, 'beginner', array['malicious software'], '{}'::text[], array['software', 'damage', 'steal'], 10),
  ('security-password', 'cybersecurity', 'Password', 'Contraseña', 'A secret sequence used to verify a user.', 'Secuencia secreta utilizada para verificar a un usuario.', 'Use a long and unique password.', 'Use a long and unique password.', null, 'beginner', array['passcode'], '{}'::text[], array['secret', 'verify', 'user'], 11),
  ('security-patch', 'cybersecurity', 'Patch', 'Parche', 'An update that fixes a software problem or vulnerability.', 'Actualización que corrige un problema o vulnerabilidad del software.', 'Install the security patch today.', 'Install the security patch today.', null, 'beginner', array['fix', 'update'], '{}'::text[], array['update', 'fix', 'vulnerability'], 12),
  ('security-phishing', 'cybersecurity', 'Phishing', 'Suplantación engañosa', 'A fraudulent attempt to steal information through deceptive messages.', 'Intento fraudulento de robar información mediante mensajes engañosos.', 'The phishing email asks for your password.', 'The phishing email asks for your password.', null, 'intermediate', array['email scam'], '{}'::text[], array['fraud', 'message', 'steal'], 13),
  ('security-privacy', 'cybersecurity', 'Privacy', 'Privacidad', 'The protection and control of personal information.', 'Protección y control de la información personal.', 'Privacy settings limit data sharing.', 'Privacy settings limit data sharing.', null, 'beginner', array['confidentiality'], '{}'::text[], array['personal', 'information', 'control'], 14),
  ('security-risk', 'cybersecurity', 'Risk', 'Riesgo', 'The possibility that a threat will cause harm.', 'Posibilidad de que una amenaza produzca daño.', 'A weak password creates a security risk.', 'A weak password creates a security risk.', null, 'beginner', array['danger'], array['safety'], array['possibility', 'threat', 'harm'], 15),
  ('security-scam', 'cybersecurity', 'Scam', 'Estafa', 'A dishonest scheme designed to deceive people.', 'Plan deshonesto diseñado para engañar a las personas.', 'The message was an online scam.', 'The message was an online scam.', null, 'beginner', array['fraud'], '{}'::text[], array['dishonest', 'deceive', 'scheme'], 16),
  ('security-threat', 'cybersecurity', 'Threat', 'Amenaza', 'Something that may exploit a weakness and cause harm.', 'Elemento que puede aprovechar una debilidad y causar daño.', 'The team identified a new network threat.', 'The team identified a new network threat.', null, 'beginner', array['danger'], array['protection'], array['weakness', 'harm', 'danger'], 17),
  ('security-token', 'cybersecurity', 'Token', 'Token de acceso', 'A digital value that represents identity or permission.', 'Valor digital que representa identidad o permiso.', 'The access token expires after one hour.', 'The access token expires after one hour.', null, 'intermediate', array['access token'], '{}'::text[], array['digital', 'identity', 'permission'], 18),
  ('security-vulnerability', 'cybersecurity', 'Vulnerability', 'Vulnerabilidad', 'A weakness that can be used to compromise a system.', 'Debilidad que puede utilizarse para comprometer un sistema.', 'The update fixes a critical vulnerability.', 'The update fixes a critical vulnerability.', null, 'intermediate', array['weakness'], array['strength'], array['weakness', 'compromise', 'system'], 19),
  ('security-antivirus', 'cybersecurity', 'Antivirus', 'Antivirus', 'Software that detects and removes malicious programs.', 'Software que detecta y elimina programas maliciosos.', 'The antivirus scans every downloaded file.', 'The antivirus scans every downloaded file.', null, 'beginner', array['security software'], '{}'::text[], array['detect', 'remove', 'malicious'], 20);
insert into public.conversation_scenarios (id, title, description, position) values
