insert into public.conversation_turns (id, scenario_id, position, bot_message, criteria, alternatives, suggestion) values
  ('standup-task', 'daily-standup', 1, 'Good morning! What task are you working on today?', array['working', 'task'], '{"working":["developing","building","implementing","creating"],"task":["profile","feature","ticket","project"]}'::jsonb, 'Try: I am working on the user profile task.'),
  ('standup-progress', 'daily-standup', 2, 'What progress have you made so far?', array['completed', 'progress'], '{"completed":["finished","implemented","built","fixed"],"progress":["advanced","improved","updated","done"]}'::jsonb, 'Try: I completed the layout and made good progress.'),
  ('standup-blocker', 'daily-standup', 3, 'Do you have any blockers or need help?', array['blocker', 'help'], '{"blocker":["blocked","issue","problem","difficulty"],"help":["support","assistance","guidance"]}'::jsonb, 'Try: I have a blocker and need help with the API.'),
  ('security-problem', 'security-report', 1, 'What security problem did you find?', array['found', 'security'], '{"found":["detected","noticed","discovered","identified"],"security":["vulnerability","incident","threat","attack"]}'::jsonb, 'Try: I found a security problem in the login form.'),
  ('security-impact', 'security-report', 2, 'What impact could this problem have?', array['data', 'risk'], '{"data":["information","records","accounts"],"risk":["danger","exposure","leak","compromise"]}'::jsonb, 'Try: User data could be at risk.'),
  ('security-action', 'security-report', 3, 'What action do you recommend?', array['recommend', 'update'], '{"recommend":["suggest","propose","should"],"update":["patch","fix","upgrade"]}'::jsonb, 'Try: I recommend an immediate security update.');
